CREATE TABLE outbox(seq BIGINT AUTO_INCREMENT PRIMARY KEY,event_id CHAR(36) NOT NULL UNIQUE, topic VARCHAR(90) NOT NULL,aggregate_id VARCHAR(80) NOT NULL,payload JSON NOT NULL);
CREATE TABLE inbox(event_id CHAR(36) PRIMARY KEY);
CREATE TABLE books(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(150) NOT NULL,author VARCHAR(100) NOT NULL,genre VARCHAR(80) NOT NULL,description TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE sku(id INT AUTO_INCREMENT PRIMARY KEY,book_id INT NOT NULL,volume INT NOT NULL,edition VARCHAR(80) NOT NULL,price INT NOT NULL,on_hand INT NOT NULL,held INT NOT NULL DEFAULT 0,FOREIGN KEY(book_id) REFERENCES books(id),UNIQUE(book_id,volume,edition),CHECK(price>0 AND on_hand>=held AND held>=0));
CREATE TABLE reservations(order_id CHAR(36) PRIMARY KEY,state VARCHAR(20) NOT NULL,lines_json JSON NOT NULL);
